<section class="container-fluid page-section"><h1 class="h2">Review katalog battle</h1><p>Hanya ruang yang diajukan penyelenggara untuk katalog member. Draf/soal privat lain tidak dibuka melalui halaman ini.</p><p><a href="<?php echo site_url('kelola/battle'); ?>">Laporan masalah</a></p><nav class="monitor-tabs mb-4" aria-label="Status pengajuan"><?php foreach (array('pending' => 'Menunggu review', 'approved' => 'Disetujui', 'rejected' => 'Ditolak', 'hidden' => 'Disembunyikan') as $key => $label): ?><a href="<?php echo site_url('kelola/battle/katalog?status='.$key); ?>"<?php echo $status === $key ? ' aria-current="page"' : ''; ?>><?php echo $label; ?></a><?php endforeach; ?></nav>
	<?php if ( ! $rooms): ?><p class="empty-card">Tidak ada pengajuan pada status ini.</p><?php else: ?><div class="row g-3"><?php foreach ($rooms as $room): ?><div class="col-lg-6"><article class="feature-card"><h2 class="h5"><?php echo html_escape($room['title']); ?></h2><p><?php echo html_escape(study_format_datetime($room['listing_requested_at'])); ?> · status ruang <?php echo html_escape($room['status']); ?></p><a class="btn btn-outline-primary" href="<?php echo site_url('kelola/battle/tinjau/'.$room['id']); ?>">Tinjau soal & kelayakan<span class="visually-hidden"> <?php echo html_escape($room['title']); ?></span></a></article></div><?php endforeach; ?></div><?php endif; ?>
	<nav class="d-flex flex-wrap gap-3 mt-4" aria-label="Halaman pengajuan"><?php if ($page > 1): ?><a href="<?php echo site_url('kelola/battle/katalog?status='.$status.'&halaman='.($page - 1)); ?>">Sebelumnya</a><?php endif; ?><span>Halaman <?php echo $page; ?>/<?php echo $page_count; ?></span><?php if ($page < $page_count): ?><a href="<?php echo site_url('kelola/battle/katalog?status='.$status.'&halaman='.($page + 1)); ?>">Berikutnya</a><?php endif; ?></nav>
</section>
